    let targetUrl = "";
    const queryUrl = url.searchParams.get('_url');
    const queryHost = url.searchParams.get('_host');
    
    if (queryUrl) {
      targetUrl = queryUrl;
    } else if (queryHost) {
      targetUrl = new URL(requestedFile, queryHost).toString();
    } else {
      targetUrl = getTargetUrl(channelUrl, requestedFile, url.search);
    }

